cat >> tests/vitest/window-manager-close-focus.test.ts <<'EOF'

describe( 'WindowManager — keep on top', () => {
	let desktop: HTMLElement;
	let manager: WindowManager;

	const z = ( w: { element: HTMLElement } ): number =>
		Number( w.element.style.zIndex );

	beforeEach( () => {
		installHooksStub();
		desktop = makeDesktop();
		document.body.appendChild( desktop );
		manager = new WindowManager( desktop );
	} );

	afterEach( () => {
		for ( const w of manager.getAll() ) {
			w.destroy();
		}
		desktop.remove();
		clearHooksStub();
	} );

	test( 'a pinned window stays above a focused window and a newly opened one', async () => {
		const a = await manager.open( cfg( 'a' ) );
		const b = await manager.open( cfg( 'b' ) );
		expect( manager.setAlwaysOnTop( 'a', true ) ).toBe( true );
		expect( a.alwaysOnTop ).toBe( true );

		manager.focus( b );
		expect( b.isFocused() ).toBe( true );
		expect( z( a ) ).toBeGreaterThan( z( b ) );

		const c = await manager.open( cfg( 'c' ) );
		expect( c.isFocused() ).toBe( true );
		expect( z( a ) ).toBeGreaterThan( z( c ) );
	} );

	test( 'pinned windows stack by focus among themselves; unpinning restores normal stacking', async () => {
		const a = await manager.open( cfg( 'a' ) );
		const b = await manager.open( cfg( 'b' ) );
		const c = await manager.open( cfg( 'c' ) );
		manager.setAlwaysOnTop( 'a', true );
		manager.setAlwaysOnTop( 'b', true );

		manager.focus( a );
		expect( z( a ) ).toBeGreaterThan( z( b ) );
		manager.focus( b );
		expect( z( b ) ).toBeGreaterThan( z( a ) );
		manager.focus( c );
		expect( Math.min( z( a ), z( b ) ) ).toBeGreaterThan( z( c ) );

		manager.setAlwaysOnTop( 'b', false );
		expect( b.alwaysOnTop ).toBe( false );
		expect( z( c ) ).toBeGreaterThan( z( b ) );
		expect( z( a ) ).toBeGreaterThan( z( c ) );
	} );

	test( 'a child of a pinned owner stays above the windows its owner is above', async () => {
		await manager.open( cfg( 'owner' ) );
		const child = await manager.openChild( 'owner', cfg( 'child' ) );
		manager.setAlwaysOnTop( 'owner', true );

		const other = await manager.open( cfg( 'other' ) );

		expect( other.isFocused() ).toBe( true );
		expect( z( child ) ).toBeGreaterThan( z( other ) );
	} );

	test( 'the title-bar toggle persists through the session snapshot and back', async () => {
		const a = await manager.open( cfg( 'a' ) );
		const changed = vi.fn();
		document.addEventListener( 'os-window-changed', changed );

		a.toggleAlwaysOnTop();

		document.removeEventListener( 'os-window-changed', changed );
		expect( a.alwaysOnTop ).toBe( true );
		expect( changed ).toHaveBeenCalledTimes( 1 );
		const saved = manager.snapshot().windows.find( ( w ) => w.id === 'a' );
		expect( saved?.alwaysOnTop ).toBe( true );

		a.destroy();
		manager._stack.length = 0;
		const restored = await manager.openNew( {
			...cfg( 'a' ),
			alwaysOnTop: saved?.alwaysOnTop,
		} );
		const b = await manager.open( cfg( 'b' ) );

		expect( restored.alwaysOnTop ).toBe( true );
		expect( z( restored ) ).toBeGreaterThan( z( b ) );
	} );
} );
EOF
